public interface LoggingProcessor {

    default void processInfo(String message) {
        logMessage("INFO", message);
    }

    default void processError(String message) {
        logMessage("ERROR", message);
    }

    // Private instance method sharing common behavior between default methods
    private void logMessage(String level, String message) {
        validateMessage(message);
        System.out.println("[" + level + "] " + java.time.Instant.now() + " - " + message);
    }

    // Private static method usable by both static and default methods
    private static void validateMessage(String message) {
        if (message == null || message.isBlank()) {
            throw new IllegalArgumentException("Message cannot be blank");
        }
    }
}
